module max_factors_power2 (\n    input wire [63:0] X,\n    output reg [4:0] k\n);\n    reg [5:0] n;\n    reg found;\n    integer i, j;\n    \n    // Priority encoder to find highest set bit (log2(X))\n    always @(*) begin\n        n = 6'd0;\n        found = 1'b0;\n        for (i = 63; i >= 0; i = i - 1) begin\n            if (!found && X[i]) begin\n                n = i[5:0];\n                found = 1'b1;\n            end\n        end\n    end\n    \n    // Find maximum k such that k*(k+1)/2 <= n\n    always @(*) begin\n        k = 5'd0;\n        for (j = 1; j <= 10; j = j + 1) begin\n            if ((j * (j + 1)) / 2 <= n) begin\n                k = j[4:0];\n            end\n        end\n    end\nendmodule